// Replay three finite QQ polynomial identities, independently of their discovery.
// Input full matrix is plain sparse3 format with target-rank header and no metadata.
// Only the listed core units and nonzero QQ constants are used to normalize rows.
#include <flint/fmpq_mpoly.h>
#include <cassert>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
using namespace std;fmpq_mpoly_ctx_t ctx;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&x):Poly(){fmpq_mpoly_set(p,x.p,ctx);}Poly(Poly&&x):Poly(){fmpq_mpoly_swap(p,x.p,ctx);}Poly&operator=(Poly x){fmpq_mpoly_swap(p,x.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void read(istream&in,Poly&p){int n;in>>n;assert(in&&n>=0);fmpq_t q;fmpq_init(q);ulong ex[3];for(int i=0;i<n;i++){string c;in>>c>>ex[0]>>ex[1]>>ex[2];assert(in&&!fmpq_set_str(q,c.c_str(),10));fmpq_canonicalise(q);fmpq_mpoly_push_term_fmpq_ui(p.p,q,ex,ctx);}fmpq_mpoly_sort_terms(p.p,ctx);fmpq_mpoly_combine_like_terms(p.p,ctx);fmpq_clear(q);}
void write(ostream&out,const Poly&p){int n=fmpq_mpoly_length(p.p,ctx);out<<n;fmpq_t q;fmpq_init(q);ulong ex[3];for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(q,p.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,p.p,i,ctx);char*c=fmpq_get_str(nullptr,10,q);out<<' '<<c;flint_free(c);for(ulong e:ex)out<<' '<<e;}out<<'\n';fmpq_clear(q);}
bool unit(Poly p,const vector<Poly>&known){if(fmpq_mpoly_is_zero(p.p,ctx))return false;Poly q;for(auto&f:known)while(fmpq_mpoly_divides(q.p,p.p,f.p,ctx))p=q;return fmpq_mpoly_is_fmpq(p.p,ctx);}
int main(int argc,char**argv){assert(argc==6);fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{ifstream input(argv[1]),unitfile(argv[2]),relations(argv[3]);ofstream normalization(argv[4]),remaining(argv[5]);assert(input&&unitfile&&relations&&normalization&&remaining);int n,m,target;input>>n>>m>>target;assert(n==63&&m==91&&target==57);vector<vector<Poly>>A(n,vector<Poly>(m));for(auto&row:A)for(auto&p:row)read(input,p);auto original=A;vector<Poly>known,multipliers(n);string line;const char*names[]={"a","e","d"};while(getline(unitfile,line)){if(line.empty())continue;Poly f;assert(!fmpq_mpoly_set_str_pretty(f.p,line.c_str(),names,ctx));known.push_back(f);}assert(known.size()==6);Poly temp;fmpq_t scalar;fmpq_init(scalar);
for(int i=0;i<n;i++){fmpq_mpoly_one(multipliers[i].p,ctx);vector<Poly>quot(m);for(auto&f:known)while(true){bool yes=true;for(int j=0;j<m;j++)if(!fmpq_mpoly_divides(quot[j].p,A[i][j].p,f.p,ctx)){yes=false;break;}if(!yes)break;A[i]=quot;fmpq_mpoly_mul(temp.p,multipliers[i].p,f.p,ctx);multipliers[i]=temp;}int first=0;while(first<m&&fmpq_mpoly_is_zero(A[i][first].p,ctx))first++;assert(first<m);fmpq_mpoly_get_term_coeff_fmpq(scalar,A[i][first].p,0,ctx);for(auto&p:A[i])fmpq_mpoly_scalar_div_fmpq(p.p,p.p,scalar,ctx);fmpq_mpoly_scalar_mul_fmpq(multipliers[i].p,multipliers[i].p,scalar,ctx);assert(unit(multipliers[i],known));for(int j=0;j<m;j++){fmpq_mpoly_mul(temp.p,A[i][j].p,multipliers[i].p,ctx);assert(fmpq_mpoly_equal(temp.p,original[i][j].p,ctx));}}
normalization<<n<<'\n';for(auto&p:multipliers)write(normalization,p);cout<<"EXACT_KNOWN_UNIT_ROW_NORMALIZATION_PASS "<<n<<'\n';
int count,rn;relations>>count>>rn;assert(count==3&&rn==n);vector<bool>deleted(n,false);for(int r=0;r<count;r++){int drop,bound;relations>>drop>>bound;assert(drop>=0&&drop<n&&!deleted[drop]);vector<Poly>v(n);for(auto&p:v)read(relations,p);for(int i=0;i<n;i++){if(deleted[i])assert(fmpq_mpoly_is_zero(v[i].p,ctx));assert(fmpq_mpoly_total_degree_si(v[i].p,ctx)<=bound);}assert(unit(v[drop],known));for(int j=0;j<m;j++){Poly sum;for(int i=0;i<n;i++)if(!fmpq_mpoly_is_zero(v[i].p,ctx)){fmpq_mpoly_mul(temp.p,A[i][j].p,v[i].p,ctx);fmpq_mpoly_add(sum.p,sum.p,temp.p,ctx);}assert(fmpq_mpoly_is_zero(sum.p,ctx));}deleted[drop]=true;cout<<"EXACT_QQ_ROW_RELATION_PASS "<<r<<" DELETED_ORIGINAL_ROW "<<drop<<'\n';}
remaining<<n-count<<' '<<m<<' '<<target<<'\n';for(int i=0;i<n;i++)if(!deleted[i])for(auto&p:A[i])write(remaining,p);cout<<"EXACT_CUBIC_REDUNDANCY_PASS "<<count<<" REMAINING_ROWS "<<n-count<<'\n';fmpq_clear(scalar);}
fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
